insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_detain','detain','verb','to officially keep someone in a place and not allow them to leave','[{"senseId":"detain_1","meaning":"to officially keep someone in a place and not allow them to leave","acceptedParaphrases":["hold","keep in custody"],"masteryContexts":[{"contextId":"u4_41_detain_meaning","text":"The police may detain a driver who refuses to take a breath test.","meaning":"to officially keep someone and not let them leave","wrongMeanings":["to ask someone to leave a place quickly","to follow someone to see where they go","to make someone wait for a short time"]},{"contextId":"u4_41_detain_paraphrase","text":"Airport officials decided to detain the passenger while they checked his documents.","meaning":"to officially stop someone from leaving a place","wrongMeanings":["to make someone arrive later than planned","to take someone to a different place","to give someone a fine for a mistake"]}],"situationDistractors":["The bus driver waved to the passengers as they left at the final stop.","A traveller bought a sandwich and sat down to wait for the evening train.","The tour guide told the group to meet beside the fountain at noon.","A porter carried the heavy bags up the steps to the platform.","The conductor checked the tickets before the train left the station.","A teenager waited at the bus stop with a bag of books."],"gapDistractors":[{"contextId":"u4_41_detain_gap_1","answer":"detain","wrong":["thank","greet","invite"]},{"contextId":"u4_41_detain_gap_2","answer":"detain","wrong":["thank","pay","photograph"]},{"contextId":"u4_41_detain_gap_3","answer":"detain","wrong":["employ","invite","thank"]}],"spellingErrors":["detane","detian","deatin","dettain","detaen","ditain"],"masteryPassages":[{"passageId":"u4_41_detain_passage_1","contextId":"u4_41_detain_gap_1","text":"Customs officers found forged documents in a lorry at the border. They have the legal power to ____ the driver until the papers have been checked.","answer":"detain"},{"passageId":"u4_41_detain_passage_2","contextId":"u4_41_detain_gap_2","text":"A passenger acted suspiciously at the airport, so security staff stopped him. Officers may ____ a person for a short time, but they must explain the reason.","answer":"detain"}],"contextDependentParaphrases":[],"wrongParaphrases":["release","welcome","follow"],"misleadingDistractors":["to make someone wait longer than they expected","to follow someone to find out where they are going","to ask someone to leave a place immediately"],"grammarForms":{"base":"detain","thirdPerson":"detains","past":"detained","pastParticiple":"detained","ing":"detaining"}}]'::jsonb,'[]'::jsonb,'["detain a suspect","detain for questioning","legally detain"]'::jsonb,'live'),
('vocab_offences','offences','noun','illegal acts, or actions that break a rule or law','[{"senseId":"offences_1","meaning":"illegal acts, or actions that break a rule or law","acceptedParaphrases":["crimes","violations of the law"],"masteryContexts":[{"contextId":"u4_42_offences_meaning","text":"Dangerous driving and speeding are among the most serious traffic offences.","meaning":"actions that break the law","wrongMeanings":["actions that are rude to other people","rules that people must follow","punishments given for breaking the law"]},{"contextId":"u4_42_offences_paraphrase","text":"The number of parking offences has risen since the new charges began.","meaning":"illegal acts that break a rule","wrongMeanings":["payments made for breaking a rule","people who break a rule","warnings given before a rule is made"]}],"situationDistractors":["The coach left the station and drove along the coast road.","A cyclist stopped to buy water at the corner shop.","The captain welcomed the visitors and showed them where the lifeboats were kept.","The new tram line carries thousands of commuters across the city every day.","A baker delivered fresh bread to the café beside the bus station.","The airline offered passengers a free drink during the long flight."],"gapDistractors":[{"contextId":"u4_42_offences_gap_1","answer":"offences","wrong":["holidays","journeys","timetables"]},{"contextId":"u4_42_offences_gap_2","answer":"offences","wrong":["festivals","journeys","souvenirs"]},{"contextId":"u4_42_offences_gap_3","answer":"offences","wrong":["holidays","festivals","timetables"]}],"spellingErrors":["offenses","ofences","offencs","offeces","offennces","offensess"],"masteryPassages":[{"passageId":"u4_42_offences_passage_1","contextId":"u4_42_offences_gap_1","text":"Last year, the traffic police gave fines to thousands of drivers. Speeding and using a phone at the wheel were the most common ____.","answer":"offences"},{"passageId":"u4_42_offences_passage_2","contextId":"u4_42_offences_gap_2","text":"The new law raises the penalty for drivers who break the rules. Drink-driving and driving without insurance are now treated as serious ____ in the city.","answer":"offences"}],"contextDependentParaphrases":[],"wrongParaphrases":["rewards","punishments","suspects"],"misleadingDistractors":["the feelings of anger caused by rude words","the punishments given to people who break the law","the people who have been found guilty of a crime"]}]'::jsonb,'[]'::jsonb,'["traffic offences","serious offences","motoring offences"]'::jsonb,'live'),
('vocab_provisional','provisional','adjective','temporary and not yet final or permanent','[{"senseId":"provisional_1","meaning":"temporary and not yet final or permanent","acceptedParaphrases":["temporary","draft"],"masteryContexts":[{"contextId":"u4_43_provisional_meaning","text":"Learner drivers must pass a test before their provisional licence becomes a full one.","meaning":"temporary and not yet permanent","wrongMeanings":["allowed only under certain conditions","very expensive to obtain","checked carefully by an expert"]},{"contextId":"u4_43_provisional_paraphrase","text":"The provisional date for the opening of the tunnel is March, but it may change.","meaning":"not yet final","wrongMeanings":["already completed and approved","made for a special occasion","cancelled for a short time"]}],"situationDistractors":["The tram stopped at the market and several passengers got on.","A porter carried two large cases to the hotel entrance.","The railway museum is open every day except Monday.","The runway was cleaned and then painted with bright new markings.","The coach stopped at a service station so that everyone could stretch their legs.","The tour guide pointed out the old bridge to the visitors."],"gapDistractors":[{"contextId":"u4_43_provisional_gap_1","answer":"provisional","wrong":["delicious","crowded","windy"]},{"contextId":"u4_43_provisional_gap_2","answer":"provisional","wrong":["tiring","windy","sleepy"]},{"contextId":"u4_43_provisional_gap_3","answer":"provisional","wrong":["wooden","crowded","hungry"]}],"spellingErrors":["provisonal","provisinal","provissional","provitional","proviscional","provisonel"],"masteryPassages":[{"passageId":"u4_43_provisional_passage_1","contextId":"u4_43_provisional_gap_1","text":"Teenagers who want to learn to drive must first apply for a ____ licence. They can exchange it for a full licence after they pass the driving test.","answer":"provisional"},{"passageId":"u4_43_provisional_passage_2","contextId":"u4_43_provisional_gap_2","text":"The railway company has announced an opening date for the new line. The date is only ____, because bad weather has delayed the building work.","answer":"provisional"}],"contextDependentParaphrases":[],"wrongParaphrases":["expensive","dangerous","popular"],"misleadingDistractors":["allowed only under certain conditions","costing more than most people can afford","checked carefully by an expert"]}]'::jsonb,'[]'::jsonb,'["provisional licence","provisional date","provisional approval"]'::jsonb,'live'),
('vocab_enforcement','enforcement','noun','the act of making sure that laws or rules are obeyed','[{"senseId":"enforcement_1","meaning":"the act of making sure that laws or rules are obeyed","acceptedParaphrases":["policing","monitoring"],"masteryContexts":[{"contextId":"u4_44_enforcement_meaning","text":"Stricter enforcement of the speed limit has reduced accidents near the school.","meaning":"making sure that a rule is obeyed","wrongMeanings":["writing a rule so that it is clear","explaining a rule to a group of people","changing a rule so that it is simpler"]},{"contextId":"u4_44_enforcement_paraphrase","text":"Without proper enforcement, many drivers ignore the parking rules.","meaning":"making sure that rules are followed","wrongMeanings":["listing rules in a book","removing rules that are old","teaching rules to children"]}],"situationDistractors":["The conductor smiled and helped a child onto the train.","Passengers waited patiently in the departure hall for the gate to open.","A taxi driver stopped to fill his tank with petrol.","A mechanic changed the tyres on the delivery van.","The ferry crossed the river every half hour from early morning.","Tourists took photographs of the famous clock tower from the bus."],"gapDistractors":[{"contextId":"u4_44_enforcement_gap_1","answer":"enforcement","wrong":["decoration","tourism","weather"]},{"contextId":"u4_44_enforcement_gap_2","answer":"enforcement","wrong":["decoration","tourism","rainfall"]},{"contextId":"u4_44_enforcement_gap_3","answer":"enforcement","wrong":["decoration","weather","tourism"]}],"spellingErrors":["enforcment","enforcemant","inforcement","enforsement","enforcemnt","enforcemment"],"wordFamilyForms":[{"form":"enforcement","partOfSpeech":"noun","example":"The city plans to hire more officers for parking enforcement.","pedagogicallyUseful":true},{"form":"enforce","partOfSpeech":"verb","example":"Police officers enforce the law by checking the speed of passing cars.","pedagogicallyUseful":true,"altExample":"Cameras help the police to enforce the speed limit on country roads."},{"form":"enforced","partOfSpeech":"adjective","example":"The seat belt law is strictly enforced on this motorway.","pedagogicallyUseful":true,"altExample":"Rules that are not enforced soon stop being respected."}],"masteryPassages":[{"passageId":"u4_44_enforcement_passage_1","contextId":"u4_44_enforcement_gap_1","text":"Many drivers ignored the speed limit on the coast road. After the police began stricter ____, the number of accidents fell sharply.","answer":"enforcement"},{"passageId":"u4_44_enforcement_passage_2","contextId":"u4_44_enforcement_gap_2","text":"The city has plenty of parking rules, but few drivers obey them. Without proper ____, the rules make little difference.","answer":"enforcement"}],"contextDependentParaphrases":[],"wrongParaphrases":["funding","training","publicity"],"misleadingDistractors":["the process of writing new laws","the punishment given to a person who breaks a rule","a document that explains the rules of the road"]}]'::jsonb,'["enforce","enforced"]'::jsonb,'["law enforcement","strict enforcement","traffic enforcement"]'::jsonb,'live'),
('vocab_statistics','statistics','noun','numbers that are collected and studied to show facts or patterns','[{"senseId":"statistics_1","meaning":"numbers that are collected and studied to show facts or patterns","acceptedParaphrases":["figures","numerical data"],"masteryContexts":[{"contextId":"u4_45_statistics_meaning","text":"The latest statistics show that more people are cycling to work.","meaning":"numbers that show facts","wrongMeanings":["opinions collected from a small group of people","pictures taken to show a place","stories told by people who were there"]},{"contextId":"u4_45_statistics_paraphrase","text":"Transport statistics on rail delays are published every month.","meaning":"numbers collected to show a pattern","wrongMeanings":["words that explain a rule","maps that show a route","prices that change often"]}],"situationDistractors":["The tourists boarded the open-top bus and took photographs of the cathedral.","A mechanic wiped the oil from his hands and closed the bonnet.","The ferry sailed slowly out of the harbour at sunset.","The taxi driver helped an elderly couple with their luggage.","The cyclist stopped at the café for a drink and a short rest.","The ship left the port early and sailed north along the coast."],"gapDistractors":[{"contextId":"u4_45_statistics_gap_1","answer":"statistics","wrong":["jokes","uniforms","souvenirs"]},{"contextId":"u4_45_statistics_gap_2","answer":"statistics","wrong":["menus","fashions","uniforms"]},{"contextId":"u4_45_statistics_gap_3","answer":"statistics","wrong":["jokes","menus","uniforms"]}],"spellingErrors":["statistcs","statisics","statictics","statistiks","stastistics","statisitcs"],"wordFamilyForms":[{"form":"statistics","partOfSpeech":"noun","example":"The tourist office keeps statistics on how many visitors arrive by train.","pedagogicallyUseful":true},{"form":"statistical","partOfSpeech":"adjective","example":"The report includes a statistical analysis of rail delays.","pedagogicallyUseful":true},{"form":"statistically","partOfSpeech":"adverb","example":"Travelling by train is statistically much safer than travelling by car.","pedagogicallyUseful":true},{"form":"statistician","partOfSpeech":"noun","example":"A statistician analysed the accident data to find the most dangerous junctions.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u4_45_statistics_passage_1","contextId":"u4_45_statistics_gap_1","text":"The transport ministry has published its yearly report. The ____ show that rail passenger numbers rose by eight per cent last year.","answer":"statistics"},{"passageId":"u4_45_statistics_passage_2","contextId":"u4_45_statistics_gap_2","text":"Planners wanted to know where most accidents happen. They studied ____ from the past five years and found three dangerous junctions.","answer":"statistics"}],"contextDependentParaphrases":[],"wrongParaphrases":["rumours","opinions","pictures"],"misleadingDistractors":["the study of numbers as a school subject","opinions given by a small group of passengers","rules that control how a transport system works"]}]'::jsonb,'["statistical","statistically","statistician"]'::jsonb,'["official statistics","accident statistics","statistics show"]'::jsonb,'live'),
('vocab_safety','safety','noun','the condition of being protected from danger, risk or injury','[{"senseId":"safety_1","meaning":"the condition of being protected from danger, risk or injury","acceptedParaphrases":["protection","freedom from danger"],"masteryContexts":[{"contextId":"u4_46_safety_meaning","text":"Child seats are designed to improve the safety of young passengers.","meaning":"protection from danger","wrongMeanings":["protection of property from thieves","the speed that is allowed on a road","the rules for building new roads"]},{"contextId":"u4_46_safety_paraphrase","text":"Cyclists should always put their own safety first when they cross a busy road.","meaning":"being free from the risk of injury","wrongMeanings":["being able to travel at high speed","having plenty of space to move","being cheap to use every day"]}],"situationDistractors":["The tour guide gave everyone a map and a bottle of water.","A baker delivered fresh rolls to the café beside the station.","The passengers clapped when the plane landed on time.","The tourists bought souvenirs at the airport shop before boarding.","A friendly steward handed out blankets to the passengers on the night train.","The taxi waited outside the hotel for the family with the suitcases."],"gapDistractors":[{"contextId":"u4_46_safety_gap_1","answer":"safety","wrong":["fashion","price","colour"]},{"contextId":"u4_46_safety_gap_2","answer":"safety","wrong":["weather","price","colour"]},{"contextId":"u4_46_safety_gap_3","answer":"safety","wrong":["fashion","weather","colour"]}],"spellingErrors":["safty","saftey","saftety","safetey","saefty","sayfety"],"wordFamilyForms":[{"form":"safety","partOfSpeech":"noun","example":"The safety of passengers is the first duty of every airline.","pedagogicallyUseful":true},{"form":"safe","partOfSpeech":"adjective","example":"The tunnel was closed until engineers could prove that it was safe.","pedagogicallyUseful":true,"altExample":"Passengers are told to stay seated until the plane reaches a safe height."},{"form":"safely","partOfSpeech":"adverb","example":"The pilot landed the aircraft safely despite the strong wind.","pedagogicallyUseful":true,"altExample":"All the children crossed the road safely with the help of the crossing guard."}],"masteryPassages":[{"passageId":"u4_46_safety_passage_1","contextId":"u4_46_safety_gap_1","text":"Every year, thousands of children learn how to cross roads carefully. Teachers say that road ____ lessons are one of the most important parts of the school year.","answer":"safety"},{"passageId":"u4_46_safety_passage_2","contextId":"u4_46_safety_gap_2","text":"Before each flight, the crew explain the exits and show how to use the life jackets. The airline says that the ____ of its passengers is always more important than the timetable.","answer":"safety"}],"contextDependentParaphrases":[],"wrongParaphrases":["speed","profit","fashion"],"misleadingDistractors":["the protection of property from thieves","the speed that is allowed on a road","the rules for building new roads"]}]'::jsonb,'["safe","safely"]'::jsonb,'["road safety","safety rules","safety measures"]'::jsonb,'live'),
('vocab_sustainability','sustainability','noun','the ability to continue without seriously damaging the environment or using up resources','[{"senseId":"sustainability_1","meaning":"the ability to continue without seriously damaging the environment or using up resources","acceptedParaphrases":["eco-friendliness","environmental responsibility"],"masteryContexts":[{"contextId":"u4_47_sustainability_meaning","text":"City planners now think about the sustainability of every new transport project.","meaning":"the ability to continue without harming the environment","wrongMeanings":["the ability to travel very fast over long distances","the ability to carry heavy loads for many hours","the ability to make a large profit each year"]},{"contextId":"u4_47_sustainability_paraphrase","text":"Public transport can improve sustainability by reducing the number of cars on the road.","meaning":"using resources without damaging the environment","wrongMeanings":["spending large sums on new projects","reducing the time that a journey takes","increasing the number of people who travel"]}],"situationDistractors":["A tourist asked the driver the price of a ticket to the airport.","The children waved to the sailors from the end of the pier.","The traveller packed a coat and a camera for the journey.","The coach driver took a break at the motorway services.","The tickets for the evening ferry sold out within an hour.","A little boy pressed his nose against the window of the train."],"gapDistractors":[{"contextId":"u4_47_sustainability_gap_1","answer":"sustainability","wrong":["disaster","laughter","curiosity"]},{"contextId":"u4_47_sustainability_gap_2","answer":"sustainability","wrong":["disaster","laughter","darkness"]},{"contextId":"u4_47_sustainability_gap_3","answer":"sustainability","wrong":["curiosity","laughter","darkness"]}],"spellingErrors":["sustainabilty","sustainibility","sustanability","sustainablity","sustainabilitty","sustenability"],"wordFamilyForms":[{"form":"sustainability","partOfSpeech":"noun","example":"Many airports now publish a yearly report on their sustainability.","pedagogicallyUseful":true},{"form":"sustainable","partOfSpeech":"adjective","example":"Electric buses are a more sustainable choice than diesel ones.","pedagogicallyUseful":true,"altExample":"The council is looking for sustainable ways to reduce city traffic."},{"form":"sustainably","partOfSpeech":"adverb","example":"The new ferries are designed to travel more sustainably than older ships.","pedagogicallyUseful":true,"altExample":"Some airlines now claim that they buy their fuel sustainably."}],"masteryPassages":[{"passageId":"u4_47_sustainability_passage_1","contextId":"u4_47_sustainability_gap_1","text":"Many cities want to reduce traffic and pollution. By building cycle lanes and electric bus routes, they hope to improve the ____ of their transport systems in the long term.","answer":"sustainability"},{"passageId":"u4_47_sustainability_passage_2","contextId":"u4_47_sustainability_gap_2","text":"The shipping company is replacing old diesel engines with cleaner ones. The managers say that ____ is now as important to them as speed and cost.","answer":"sustainability"}],"contextDependentParaphrases":[],"wrongParaphrases":["affordability","popularity","reliability"],"misleadingDistractors":["the strength of a bridge or a building","the quality of being cheap to produce","the speed at which a project is completed"]}]'::jsonb,'["sustainable","sustainably"]'::jsonb,'["environmental sustainability","long-term sustainability","improve sustainability"]'::jsonb,'live'),
('vocab_legislation','legislation','noun','laws considered together, especially laws made by a government','[{"senseId":"legislation_1","meaning":"laws considered together, especially laws made by a government","acceptedParaphrases":["laws","laws made by the government"],"masteryContexts":[{"contextId":"u4_48_legislation_meaning","text":"The government is planning new legislation to control the use of electric scooters.","meaning":"laws made by a government","wrongMeanings":["one official rule about an activity","the act of making sure laws are obeyed","a group of people who decide policy"]},{"contextId":"u4_48_legislation_paraphrase","text":"Road safety legislation has changed several times in the last twenty years.","meaning":"laws considered together","wrongMeanings":["a single rule on one road","a punishment for breaking a law","a plan to improve a road"]}],"situationDistractors":["The pilot welcomed the passengers and pointed out the exits.","A cyclist rode past the market and stopped at the traffic lights.","The tourists took a taxi from the hotel to the railway station.","The passengers queued patiently at the bus station for the late coach.","The engineer cleaned the lenses of the signal lights beside the track.","A group of students took photographs of the tram from the bridge."],"gapDistractors":[{"contextId":"u4_48_legislation_gap_1","answer":"legislation","wrong":["entertainment","furniture","scenery"]},{"contextId":"u4_48_legislation_gap_2","answer":"legislation","wrong":["entertainment","scenery","weather"]},{"contextId":"u4_48_legislation_gap_3","answer":"legislation","wrong":["furniture","scenery","weather"]}],"spellingErrors":["legislaton","legeslation","legislashun","ledgislation","legislasion","lesgislation"],"wordFamilyForms":[{"form":"legislation","partOfSpeech":"noun","example":"Strict legislation controls the hours that bus drivers may work.","pedagogicallyUseful":true},{"form":"legislate","partOfSpeech":"verb","example":"Parliament has the power to legislate on matters such as seat belts and speed limits.","pedagogicallyUseful":true},{"form":"legislative","partOfSpeech":"adjective","example":"The legislative process can take years before a new road law is passed.","pedagogicallyUseful":true},{"form":"legislator","partOfSpeech":"noun","example":"One legislator argued that the speed limit should be lower near schools.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u4_48_legislation_passage_1","contextId":"u4_48_legislation_gap_1","text":"Electric scooters have become popular, but there are few clear rules about where they can be used. Parliament is now discussing new ____ to control them.","answer":"legislation"},{"passageId":"u4_48_legislation_passage_2","contextId":"u4_48_legislation_gap_2","text":"The government wants to cut pollution from lorries. It has promised tougher ____ on exhaust fumes before the end of the year.","answer":"legislation"}],"contextDependentParaphrases":[],"wrongParaphrases":["taxes","prices","crimes"],"misleadingDistractors":["one official rule about a particular activity","the act of making sure that laws are obeyed","a group of people who discuss and decide policy"]}]'::jsonb,'["legislate","legislative","legislator"]'::jsonb,'["new legislation","pass legislation","traffic legislation"]'::jsonb,'live'),
('vocab_introduce','introduce','verb','to bring something into use for the first time','[{"senseId":"introduce_1","meaning":"to bring something into use for the first time","acceptedParaphrases":["bring in","start using"],"masteryContexts":[{"contextId":"u4_49_introduce_meaning","text":"The government will introduce a new speed limit on country roads next year.","meaning":"to bring into use for the first time","wrongMeanings":["to remove from use after many years","to repair after it has broken","to explain to a group of visitors"]},{"contextId":"u4_49_introduce_paraphrase","text":"Airlines will introduce electronic boarding passes at every airport this summer.","meaning":"to start to use something new","wrongMeanings":["to stop something old","to continue something familiar","to repeat something many times"]}],"situationDistractors":["The captain waved to the crowd from the bridge of the ship.","Tourists queued outside the museum to buy their tickets.","A mechanic tightened the bolts on the wheel of the van.","The porter pushed the trolley of suitcases along the platform.","The captain thanked the crew after the ship reached the harbour.","The old tram rattled slowly along the main street towards the market."],"gapDistractors":[{"contextId":"u4_49_introduce_gap_1","answer":"introduce","wrong":["forget","swallow","translate"]},{"contextId":"u4_49_introduce_gap_2","answer":"introduce","wrong":["forget","sneeze","translate"]},{"contextId":"u4_49_introduce_gap_3","answer":"introduce","wrong":["swallow","sneeze","translate"]}],"spellingErrors":["introduse","intruduce","introdyce","intorduce","introduc","entroduce"],"masteryPassages":[{"passageId":"u4_49_introduce_passage_1","contextId":"u4_49_introduce_gap_1","text":"Traffic in the city centre has become much worse. The council has decided to ____ a charge for cars that enter the centre during the day.","answer":"introduce"},{"passageId":"u4_49_introduce_passage_2","contextId":"u4_49_introduce_gap_2","text":"Passengers often wait a long time to buy paper tickets. From next month, the airline will ____ electronic boarding passes at every airport it serves.","answer":"introduce"}],"contextDependentParaphrases":[],"wrongParaphrases":["take away","look at","send back"],"misleadingDistractors":["to say who someone is when two people meet","to remove an old system that no longer works","to test something before it is sold"],"grammarForms":{"base":"introduce","thirdPerson":"introduces","past":"introduced","pastParticiple":"introduced","ing":"introducing"}}]'::jsonb,'[]'::jsonb,'["introduce a law","introduce new rules","introduce a scheme"]'::jsonb,'live'),
('vocab_innovative','innovative','adjective','using new ideas or methods in an original and effective way','[{"senseId":"innovative_1","meaning":"using new ideas or methods in an original and effective way","acceptedParaphrases":["original","pioneering"],"masteryContexts":[{"contextId":"u4_50_innovative_meaning","text":"The airline is famous for its innovative approach to reducing waste on board.","meaning":"using new ideas in an original way","wrongMeanings":["following old and trusted methods","costing very little to produce","attracting very large crowds"]},{"contextId":"u4_50_innovative_paraphrase","text":"Engineers have designed an innovative bridge that makes its own electricity.","meaning":"new and effective in an original way","wrongMeanings":["old and well known to everyone","large and difficult to move","cheap and easy to copy"]}],"situationDistractors":["The old ferry carried passengers across the river every hour.","A boy bought a ticket and ran to catch the last bus.","The driver parked the van beside the harbour wall.","The family waited at the harbour for the ferry to arrive.","A taxi stopped outside the museum at ten o’clock.","The traveller read a newspaper while the coach drove through the hills."],"gapDistractors":[{"contextId":"u4_50_innovative_gap_1","answer":"innovative","wrong":["ordinary","traditional","heavy"]},{"contextId":"u4_50_innovative_gap_2","answer":"innovative","wrong":["ordinary","historic","heavy"]},{"contextId":"u4_50_innovative_gap_3","answer":"innovative","wrong":["traditional","ordinary","historic"]}],"spellingErrors":["inovative","inovvative","inivative","innovatve","innovitive","innovativ"],"wordFamilyForms":[{"form":"innovative","partOfSpeech":"adjective","example":"The city won a prize for its innovative cycle-sharing scheme.","pedagogicallyUseful":true},{"form":"innovate","partOfSpeech":"verb","example":"Car makers must innovate to meet the demand for cleaner vehicles.","pedagogicallyUseful":true},{"form":"innovation","partOfSpeech":"noun","example":"Folding bicycles were an important innovation in city transport.","pedagogicallyUseful":true},{"form":"innovator","partOfSpeech":"noun","example":"Engineers regard her as an innovator who changed the way trains are built.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u4_50_innovative_passage_1","contextId":"u4_50_innovative_gap_1","text":"Engineers in the city have designed a bridge that produces its own electricity from passing traffic. The design is so ____ that experts from many countries have visited to study it.","answer":"innovative"},{"passageId":"u4_50_innovative_passage_2","contextId":"u4_50_innovative_gap_2","text":"The company wanted to solve the problem of crowded trains. Its ____ idea was to use the space under the seats for luggage, which made room for more passengers.","answer":"innovative"}],"contextDependentParaphrases":[],"wrongParaphrases":["ordinary","crowded","expensive"],"misleadingDistractors":["following old methods that have been used for many years","recently built or recently bought","very popular with young people"]}]'::jsonb,'["innovate","innovation","innovator"]'::jsonb,'["innovative design","innovative technology","highly innovative"]'::jsonb,'live')
